import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>SVG'yi PNG'ye dönüştürmek birkaç dakikalık bir iştir. Program kurmazsınız, dosyanız cihazınızdan ayrılmaz ve sonunda istediğiniz boyutta keskin bir PNG indirirsiniz.</p>\n<p>Bu yazı, işlemi altı adımda anlatıyor. İster tek bir logo ister bütün bir simge paketi dönüştürün, adımlar aynıdır.</p>\n<p>Sonunda doğru boyutu nasıl seçeceğinizi, yaygın sorunları nasıl çözeceğinizi ve farklı kullanım alanları için hangi ölçeğin işe yaradığını öğreneceksiniz.</p>\n<h2 id=\"before-you-start\">Başlamadan önce: SVG'yi hazırlayın</h2>\n<p>Önce SVG dosyanızı bulun. Logo ya da simge, bilgisayarınızda ya da indirilenler klasöründe olabilir.</p>\n<p>SVG'yi tarayıcıda açıp kontrol edin. Eksik görsel ya da bozuk yazı tipi varsa dönüştürmeden önce düzeltin.</p>\n<p>Hedef boyutu belirleyin: simge mi, kartvizit mi, afiş mi? Hedef, ölçek seçimini kolaylaştırır.</p>\n<h2 id=\"step-1-open-tool\">Adım 1: SVG'den PNG'ye aracını açın</h2>\n<p>Tarayıcınızda SVG'den PNG'ye aracını açın. Sayfa hemen yüklenir; hesap açmanız ya da program kurmanız gerekmez.</p>\n<p>Dönüştürme tamamen tarayıcıda yapılır. Dosyalarınız yüklenmez; gizli ya da müşteri işlerini rahatça çevirebilirsiniz.</p>\n<h2 id=\"step-2-upload\">Adım 2: SVG dosyalarınızı yükleyin</h2>\n<p>Dosyaları yükleme alanına sürükleyin ya da dosya seçiciyle seçin. Birden fazla SVG'yi aynı anda seçebilirsiniz.</p>\n<p>Dosyalar listede görünür; her birinin adı yazılır. Yanlış bir dosya eklediyseniz listeden kaldırabilirsiniz.</p>\n<h2 id=\"step-3-scale\">Adım 3: çıktı ölçeğini seçin</h2>\n<p>Ölçek kaydırıcısıyla çıktı boyutunu seçin. 1x, SVG'nin tanımlı boyutunda PNG üretir; 2x iki katı büyüklüğünde üretir.</p>\n<p>Retina ekranlar için 2x ya da 3x kullanın. Baskı için 4x ya da üzeri gerekir; web için 2x genellikle yeterlidir.</p>\n<h2 id=\"step-4-convert\">Adım 4: dosyaları dönüştürün</h2>\n<p>Dönüştür düğmesine basın. Araç her dosyayı sırayla rasterleştirir; ilerleme çubuğu durumu gösterir.</p>\n<p>Dönüştürme genellikle birkaç saniye sürer. Karmaşık SVG'ler ya da büyük ölçekler biraz daha uzun sürebilir.</p>\n<h2 id=\"step-5-check\">Adım 5: sonucu kontrol edin</h2>\n<p>Dönüştürmeden sonra önizlemeyi açın. Kenarların keskin olduğunu ve renklerin doğru göründüğünü doğrulayın.</p>\n<p>Yüzde 100 yakınlaştırmayla inceleyin. Bulanıklık ya da eksik öğe görürseniz ölçeği artırıp yeniden dönüştürün.</p>\n<h2 id=\"step-6-download\">Adım 6: PNG dosyalarını indirin</h2>\n<p>Her dosyayı tek tek indirebilir ya da tamamını ZIP olarak alabilirsiniz. ZIP, simge paketleri için çok pratiktir.</p>\n<p>İndirilen dosyaların adlarını kontrol edin. Orijinal ad korunur; yalnızca uzantı .png olur.</p>\n<ol>\n<li>SVG'den PNG'ye aracını açın ve SVG dosyalarınızı yükleyin.</li>\n<li>Çıktı ölçeğini seçin; retina için 2x, baskı için 4x.</li>\n<li>Dönüştürün ve sonucu önizlemede kontrol edin.</li>\n<li>PNG dosyalarını tek tek ya da ZIP olarak indirin.</li>\n</ol>\n<h2 id=\"converting-an-icon-pack\">Bir simge paketinin tamamını dönüştürmek</h2>\n<p>Tüm simge SVG'lerini aynı anda seçin. Yüklenirler ve tek tıklamayla hepsi PNG olur.</p>\n<p>Tüm simgeler için aynı ölçeği kullanın. Tutarlılık setin her yerde aynı görünmesini sağlar.</p>\n<p>Dönüştürmeden sonra simgeleri kontrol edin. Eksik öğe ya da bozuk yazı tipi varsa kaynağı düzeltip yeniden dönüştürün.</p>\n<h2 id=\"choosing-size-for-purpose\">Her kullanım için boyut seçmek</h2>\n<p>Web simgeleri için 2x ölçek yeterlidir. 24 piksellik simge, 48 piksellik keskin bir PNG olur.</p>\n<p>Sosyal medya için platformun istediği boyuta uyun. Yanlış boyut kırpılır; önce boyut kurallarını öğrenin.</p>\n<p>Baskı için 300 DPI hedefleyin. Kartvizitteki küçük bir logo bile yüksek ölçek ister.</p>\n<h2 id=\"fixing-problems\">Yaygın sorunları çözmek</h2>\n<p>Bulanık PNG genelde düşük ölçekten kaynaklanır. Ölçeği artırıp yeniden dönüştürün.</p>\n<p>Eksik yazı tipi metnin farklı görünmesine yol açar. Metni yola dönüştürün ya da yazı tipini yükleyin.</p>\n<p>Eksik fotoğraf bağlantılı görselden kaynaklanır. Görseli SVG'ye gömün ve yeniden dönüştürün.</p>\n<h2 id=\"mobile-tips\">Telefon ve tablet ipuçları</h2>\n<p>Modern telefon tarayıcıları aracı tam destekler. Telefonda dosya seçip çevirebilir ve indirebilirsiniz.</p>\n<p>Telefonda indirilenler genelde İndirilenler klasörüne gider. Bulamazsanız tarayıcının indirme listesini açın.</p>\n<p>Çok dosyalı dönüştürme bilgisayarda daha rahattır. Toplu işlerde masaüstünü tercih edin.</p>\n<h2 id=\"logo-for-business-card\">Kartvizit için logo dönüştürmek</h2>\n<p>Kartvizit için yüksek ölçek gerekir. Küçük basılacak bir logo bile 300 DPI için büyük piksel ister.</p>\n<p>Logoyu 4x ölçekle dönüştürün. Baskı merkezine göndermeden önce yüzde 100 yakınlaştırmayla kontrol edin.</p>\n<p>Renk modunu kontrol edin. Baskıda CMYK gerekebilir; SVG genelde RGB'dir.</p>\n<h2 id=\"icons-for-website\">Web sitesi için simge dönüştürmek</h2>\n<p>Web simgeleri için 2x ölçek kullanın. Retina ekranlarda keskin görünürler.</p>\n<p>Tüm simgelerde aynı ölçeği kullanın. Tutarlı bir set, sitede profesyonel görünür.</p>\n<p>Simgeleri sitede test edin. Küçük boyutlarda bile kenarların temiz kaldığını doğrulayın.</p>\n<h2 id=\"svg-for-tshirt-print\">Tişört baskısı için SVG dönüştürmek</h2>\n<p>Tişört baskısı için çok yüksek ölçek gerekir. Büyük basılacak görsel, binlerce piksel ister.</p>\n<p>Baskı merkezine sormaktan çekinmeyin. Hangi boyutu ve formatı istediklerini öğrenmek, boşa giden baskıyı önler.</p>\n<p>Renkleri kontrol edin. Baskıda renkler ekrandan farklı görünebilir; prova baskısı isteyin.</p>\n<h2 id=\"svg-for-presentation\">Sunum için SVG dönüştürmek</h2>\n<p>Sunumlarda PNG tercih edin. Salonun bilgisayarı eski olabilir; PNG her makinede açılır.</p>\n<p>Slayt görselleri için 2x ölçek yeterlidir. Projektörde keskin görünürler.</p>\n<p>Sunumdan önce dosyaları çevrimdışı test edin. Görsellerin açıldığından emin olun.</p>\n<h2 id=\"svg-for-favicon\">Favicon için SVG dönüştürmek</h2>\n<p>Modern tarayıcılar SVG favicon destekler ama her tarayıcı desteklemez. Güvenli seçim PNG favicon'dır.</p>\n<p>Favicon için 32x32 ve 16x16 boyutunda PNG üretin. Küçük boyutlarda sade logolar daha iyi görünür.</p>\n<p>Favicon'ı tarayıcıda deneyin. Sekmede net göründüğünden emin olun.</p>\n<h2 id=\"svg-for-website-banner\">Web sitesi afişi için SVG dönüştürmek</h2>\n<p>Afiş için 2x ölçek kullanın. Geniş görseller yüksek yoğunluklu ekranlarda keskin olmalıdır.</p>\n<p>Afiş boyutunu tasarıma göre seçin. Yanlış boyut, sayfa düzenini bozar.</p>\n<p>Afişi sitede test edin. Farklı ekran boyutlarında nasıl göründüğünü kontrol edin.</p>\n<p>Adım adım ilerleyin ve her dosyayı indirmeden önce kontrol edin. Kılavuzun tamamı için <a href=\"/tr/blog/svg-png-ye-donustur-rehberi\">SVG'den PNG'ye kılavuzuna</a> bakın; karşılaştırma için <a href=\"/tr/blog/svg-vs-png-vektor-raster\">SVG ve PNG karşılaştırması</a> yardımcı olur. Genel dönüştürmeler için <a href=\"/tr/gorsel-donustur\">görsel dönüştürücü</a> de elinizin altındadır; araç ise <a href=\"/tr/svg-png-ye-donustur\">SVG'den PNG'ye dönüştürücü</a> sayfasındadır.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"1x ölçekte PNG ne kadar büyük olur?","answer":"1x ölçek, SVG'nin tanımlı boyutunda PNG üretir. Örneğin 24 piksellik bir simge 1x ölçekte 24 piksellik PNG olur. Retina ekranlar için 2x ya da 3x kullanın; baskı için 4x ya da üzeri gerekir."},{"question":"SVG dosyalarını telefonumda dönüştürebilir miyim?","answer":"Evet, modern mobil tarayıcılar aracı tam olarak destekler. Telefonda dosya seçip dönüştürebilir ve sonucu indirebilirsiniz. Çok sayıda dosyayı dönüştürmek bilgisayarda daha rahat olur; toplu işler için masaüstünü tercih edin."},{"question":"Dışa aktarılan PNG hangi dosya adını korur?","answer":"Orijinal SVG'nin adını korur; yalnızca uzantı .png olur. Böylece referansları güncellemek kolaylaşır. Toplu dönüştürmede ZIP içindeki adlar da aynı kuralı izler."},{"question":"Dönüştürücü SVG animasyonlarını destekler mi?","answer":"Hayır. PNG hareketsiz bir formattır; dönüştürücü animasyonun yalnızca ilk karesini rasterleştirir. Animasyonu korumak istiyorsanız GIF ya da video formatını kullanın."},{"question":"Data URI olarak gömülü görseli olan bir SVG'yi rasterleştirebilir miyim?","answer":"Evet. Data URI olarak gömülen görseller SVG'nin parçasıdır ve dönüştürmede kaybolmaz. Sorun yalnızca dış dosyaya bağlantı veren SVG'lerde yaşanır; o görselleri önce SVG'ye gömün."},{"question":"Dönüştürülen PNG'm neden bulanık görünüyor?","answer":"Genellikle ölçek çok düşüktür. 1x ölçekte üretilen küçük bir PNG büyütüldüğünde bulanıklaşır. Ölçeği 2x ya da 3x'e artırıp yeniden dönüştürün; kaynak SVG vektör olduğu için her ölçekte keskin üretim yapar."}];
